        if (msg.sig != expectedSelector) {
            revert UnexpectedGovernanceSelector(msg.sig, expectedSelector);
        }
        (
            bool executing,
            bytes32 actionId,
            uint8 actionClass,
            bytes32 scopeHash,
            bytes32 oldValueHash,
            bytes32 newValueHash
        ) = governanceExecutor.currentAction();
